class Solution { public long maxBalancedSubsequenceSum(int[] nums){int n=nums.length;long[] keys=new long[n],sorted=new long[n];for(int i=0;i<n;i++)keys[i]=sorted[i]=(long)nums[i]-i;Arrays.sort(sorted);int unique=0;for(long key:sorted)if(unique==0||sorted[unique-1]!=key)sorted[unique++]=key;long[] tree=new long[unique+1];long answer=Long.MIN_VALUE;for(int i=0;i<n;i++){int rank=Arrays.binarySearch(sorted,0,unique,keys[i])+1;long best=0;for(int x=rank;x>0;x-=x&-x)best=Math.max(best,tree[x]);long current=nums[i]+best;answer=Math.max(answer,current);for(int x=rank;x<=unique;x+=x&-x)tree[x]=Math.max(tree[x],current);}return answer;} }
